INSERT INTO tasks (id, title, description, deadline, created_by, created_at, hints) VALUES ('b20813dc-fe51-4292-a54b-3201295be84b', 'Task 1: Headings Practice (H1 to H6)', 'Create a simple HTML page using all heading tags from h1 to h6. Instructions: Create an HTML file (e.g., task1.html) Inside the <body>, add the following: <h1> → Your Name <h2> → Your Course/Field (e.g., Web Development) <h3> → Your Institute/School <h4> → Your City <h5> → Your Favorite Hobby <h6> → Today’s Date <br><strong>Reference Asset:</strong> <a href=https://res.cloudinary.com/dwowte8ny/image/upload/v1772645569/Screenshot_2026-03-04_223137_kbxqwo.png target=_blank class=text-indigo-500 hover:underline>View Attachment</a>', '2026-03-05 10:00:00+00', NULL, '2026-03-04 17:32:50.1903+00', '');
INSERT INTO tasks (id, title, description, deadline, created_by, created_at, hints) VALUES ('3327ade9-460f-4b99-97a7-c5f65e591f46', '📝 Task 2: Paragraph and Text Formatting', 'Create a simple HTML page using paragraph and basic text formatting tags. Instructions: Create an HTML file (e.g., task2.html) Inside the <body>, add the following: A main heading (h1) with the text: About Me A paragraph describing yourself (4–5 lines) Inside the paragraph, use these formatting tags: <b> for bold text <i> for italic text <u> for underlined text <br> for a line break Example idea: Write about your studies, skills, or hobbies. <br><strong>Reference Asset:</strong> <a href=https://res.cloudinary.com/dwowte8ny/image/upload/v1772733832/Screenshot_2026-03-04_223137_irv1ne.png target=_blank class=text-indigo-500 hover:underline>View Attachment</a>', '2026-03-06 11:00:00+00', NULL, '2026-03-05 18:03:55.567214+00', '');
INSERT INTO tasks (id, title, description, deadline, created_by, created_at, hints) VALUES ('2b2e649f-6ea8-4aa2-85db-da98b7126703', '📝 Task 3: Create Lists in HTML', 'Create a simple HTML page using ordered and unordered lists. Instructions: Create an HTML file (e.g., task3.html) Inside the <body>, add the following: A heading (h1) with the text: My Skills An unordered list (ul) containing at least 5 skills Then add: Another heading (h2) with the text: Daily Routine An ordered list (ol) containing at least 5 daily activities <br><strong>Reference Asset:</strong> <a href=https://res.cloudinary.com/dwowte8ny/image/upload/v1772900343/task3_q6f3wx.png target=_blank class=text-indigo-500 hover:underline>View Attachment</a>', '2026-03-09 11:00:00+00', NULL, '2026-03-07 16:19:04.68855+00', '');
INSERT INTO tasks (id, title, description, deadline, created_by, created_at, hints) VALUES ('d9bf939e-7620-4ea6-b0a5-4f3ae9dda0c2', '📝 Task 5 – Styled Student Table (HTML + CSS)', 'Create a Student Information Table using HTML and CSS. Requirements Add a page heading: Student Information Table Create a table with 6 columns: ID Name Course City Email Status Add at least 6 student records. CSS Requirements Table should be center aligned Table width 70% Add padding inside cells Header background color should be dark Text color of header should be white Add hover effect on rows Add border-collapse <br><strong>Reference Asset:</strong> <a href=https://res.cloudinary.com/dwowte8ny/image/upload/v1773246913/task5_tvrk5f.png target=_blank class=text-indigo-500 hover:underline>View Attachment</a>', '2026-03-12 11:00:00+00', NULL, '2026-03-11 16:34:22.397859+00', '');
INSERT INTO tasks (id, title, description, deadline, created_by, created_at, hints) VALUES ('677e9b88-0253-446c-bf34-e6e847094967', '📝 Task 4: Links and Images in HTML', 'Create a simple HTML page using links and images. Instructions Create an HTML file (e.g., task4.html) Inside the <body>, add the following: A heading (h1) with the text: My Favorite Website Add a link (anchor tag) that opens Google in a new tab Add another heading (h2) with the text: My Favorite Image Insert an image using the <img> tag Set width = 300px Add alt text for the image <br><strong>Reference Asset:</strong> <a href=https://res.cloudinary.com/dwowte8ny/image/upload/v1773070663/task4_jzggl3.png target=_blank class=text-indigo-500 hover:underline>View Attachment</a>', '2026-03-10 11:00:00+00', NULL, '2026-03-09 15:37:44.382807+00', '');
